import math


class pytest:
    # A stand-in for pytest, which this page cannot load.
    # In your project, delete this class and write: import pytest
    class approx:
        def __init__(self, expected, rel=None, abs=None):
            self.expected, self.rel, self.abs = expected, rel, abs

        def __eq__(self, actual):
            if isinstance(self.expected, (list, tuple)):
                return (isinstance(actual, (list, tuple)) and len(actual) == len(self.expected)
                        and all(a == pytest.approx(e, self.rel, self.abs) for a, e in zip(actual, self.expected)))
            if self.rel is None and self.abs is not None:
                gap = self.abs
            else:
                rel = 1e-6 if self.rel is None else self.rel
                gap = max(rel * abs(self.expected), 1e-12 if self.abs is None else self.abs)
            return abs(actual - self.expected) <= gap


def total_return(prices):
    # the return over the whole path, first price to last
    return prices[-1] / prices[0] - 1


def test_two_rises():
    # £100.00, then £110.00, then £121.00: two rises of 10%
    # 121 / 100 - 1 = 0.21 on paper
    assert total_return([100.00, 110.00, 121.00]) == pytest.approx(0.21)
